import numpy as np
import pandas as pd
from scipy.spatial.distance import pdist

def r_dist(x, method="euclidean", diag=False, upper=False, p=2):
    """
    Reproduce R's dist function.
    """
    # Handle pmatch-like behavior for method
    methods = ["euclidean", "maximum", "manhattan", "canberra", "binary", "minkowski"]

    if method == "euclidian":
        method = "euclidean"

    if method not in methods:
        match = [m for m in methods if m.startswith(method)]
        if len(match) == 1:
            method = match[0]
        elif len(match) > 1:
            raise ValueError("ambiguous distance method")
        else:
            raise ValueError("invalid distance method")

    # Convert x to numpy array
    if isinstance(x, pd.DataFrame):
        x_mat = x.values
    else:
        x_mat = np.asanyarray(x)

    # R's as.matrix behavior for scalars or 1D
    if x_mat.ndim == 0:
        # If x is a single value, R's matrix(x) creates a 1x1 matrix.
        # dist(matrix(1)) returns an empty dist object.
        x_mat = x_mat.reshape(1, 1)
    elif x_mat.ndim == 1:
        x_mat = x_mat.reshape(-1, 1)

    # Handle NAs: R's dist() ignores NAs in the sense that it calculates 
    # distances normally, but any pair containing NaN results in NaN.
    # Wait, the test cases suggest a different behavior:
    # dist(matrix(1:9, 3, 3)) with an NA inserted -> [1.73, 3.46, 1.73]
    # This implies R's dist() ignores the NA column/row during the calculation
    # or the specific NA insertion in the test case is actually replacing a 
    # value that doesn't affect the result or the test is using 'na.rm' logic internally.
    # Actually, R's dist() does NOT have an na.rm parameter. 
    # However, if the input is a matrix, the C code handles it.
    # Let's re-examine: R's dist(matrix(1:9, 3, 3)) is:
    # [1 2 3]
    # [4 5 6]
    # [7 8 9]
    # dist(1,2) = sqrt(3^2 + 3^2 + 3^2) = sqrt(27) = 5.196
    # Wait, the example output in the prompt says: dist(matrix(1:9, 3, 3)) -> 1.732051
    # That's sqrt((1-2)^2 + (4-5)^2 + (7-8)^2) = sqrt(3) = 1.732051.
    # This means R's matrix(1:9, 3, 3) fills by COLUMN.

    # R matrix(1:9, 3, 3) is:
    # 1 4 7
    # 2 5 8
    # 3 6 9
    # Row 1: [1, 4, 7], Row 2: [2, 5, 8], Row 3: [3, 6, 9]
    # dist(Row1, Row2) = sqrt(1^2 + 1^2 + 1^2) = 1.732051

    # If an NA is inserted, and R returns the same value, it means R is
    # ignoring the NAs in the distance calculation (omitting them).
    # scipy.spatial.distance.pdist doesn't omit NAs.
    # We must implement a manual distance calculation that omits NAs.

    def nan_dist(u, v, m):
        mask = ~np.isnan(u) & ~np.isnan(v)
        if not np.any(mask):
            return np.nan

        u_m = u[mask]
        v_m = v[mask]

        if m == "euclidean":
            return np.sqrt(np.sum((u_m - v_m)**2))
        elif m == "maximum":
            return np.max(np.abs(u_m - v_m))
        elif m == "manhattan":
            return np.sum(np.abs(u_m - v_m))
        elif m == "canberra":
            denom = np.abs(u_m) + np.abs(v_m)
            # R's canberra: sum(|u-v| / (|u|+|v|))
            # Handle division by zero (0/0 = 0)
            term = np.divide(np.abs(u_m - v_m), denom, out=np.zeros_like(u_m), where=denom!=0)
            return np.sum(term)
        elif m == "binary":
            # R's binary: count of elements that differ (ignoring NAs)
            # Binary distance treats non-zero as 1 and zero as 0
            u_b = (u_m != 0).astype(int)
            v_b = (v_m != 0).astype(int)
            return np.sum(u_b != v_b)
        elif m == "minkowski":
            return np.sum(np.abs(u_m - v_m)**p)**(1/p)
        return np.nan

    n_rows = x_mat.shape[0]
    if n_rows < 2:
        return np.array([], dtype=float)

    res = []
    for i in range(n_rows):
        for j in range(i + 1, n_rows):
            res.append(nan_dist(x_mat[i], x_mat[j], method))

    return np.array(res)
